mapper.select:
SELECT tb.id_batch AS idBatch, tb.batch_number AS batchNumber, tb.quantity_available AS quantityAvailable, tb.initial_quantity AS initialQuantity, tb.manufacturing_date AS manufacturingDate, tb.expiration_date AS expirationDate, tb.product_id AS productId, tp.name AS productName, tb.location_id AS locationId, tl.aisle, tl.bin, tl.shelf, tl.description, tb.unit_price AS unitPrice, tb.active FROM stock_schema.tb_batch tb INNER JOIN stock_schema.tb_product tp ON tp.id_product = tb.product_id INNER JOIN stock_schema.tb_location tl ON tl.id_location = tb.location_id
AND tb.product_id IN
#{id}
AND tb.batch_number = #{batchNumber}
AND tl.aisle = #{aisle}
AND tb.active = #{active}
AND tb.expiration_date <= DATE_ADD(CURDATE(), INTERVAL #{nearExpirationDays} DAY)
AND tb.expiration_date < CURDATE()
ORDER BY tb.expiration_date ASC
